<?php
declare(strict_types=1);
require __DIR__.'/../vendor/autoload.php';
use MiniErp\Repositories\StockRepository;
$cfg=require __DIR__.'/../config.php';$d=$cfg['db'];$pdo=new PDO("mysql:host={$d['host']};port={$d['port']};dbname=mini_erp_tenant_14;charset=utf8mb4",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$tenant=14;$product=(int)$pdo->query('SELECT id FROM produtos ORDER BY id LIMIT 1')->fetchColumn();if($product<1){echo"StockLotControl SKIPPED no-product\n";exit;}$pdo->beginTransaction();try{$repo=new StockRepository($pdo,$tenant);$main=$repo->ensureMainLocation();$suffix=bin2hex(random_bytes(4));$second=$repo->createLocation('TEST ONLY '.$suffix,'TEST_'.$suffix);$lot=$repo->createLot($product,$main,'LOT-'.$suffix,'10.0000',null,date('Y-m-d',strtotime('+1 year')),'TEST ONLY initial',999);$repo->setBlocked($lot,true,'TEST ONLY block',999);$blocked=array_values(array_filter($repo->lots($product),fn($row)=>(int)$row['id']===$lot))[0]??null;if(!$blocked||empty($blocked['blocked_sale']))throw new RuntimeException('block');$repo->setBlocked($lot,false,'',999);$repo->adjust($lot,'LOSS','2.0000','TEST ONLY loss',999);$repo->adjust($lot,'YIELD','1.0000','TEST ONLY yield',999);$repo->transfer($lot,$second,'3.0000','TEST ONLY transfer',999);$repo->receive($product,$main,'LOT-'.$suffix,'2.0000','TEST ONLY invoice entry',999,'TEST',123);$entryOrder=987654321;$repo->receiveEntryOrder($entryOrder,[['product_id'=>$product,'quantity'=>'1.0000']],999);$repo->receiveEntryOrder($entryOrder,[['product_id'=>$product,'quantity'=>'1.0000']],999);$lots=array_values(array_filter($repo->lots($product),fn($row)=>str_contains((string)$row['lot_code'],$suffix)||$row['lot_code']==='ENTRADA-'.$entryOrder.'-'.$product));$sum=array_sum(array_map(fn($row)=>(float)$row['quantity_available'],$lots));if(count($lots)!==3||abs($sum-12.0)>.0001)throw new RuntimeException('balance/idempotency');$types=array_column($repo->movements(30),'movement_type');foreach(['INITIAL','BLOCK','UNBLOCK','LOSS','YIELD','TRANSFER','ENTRY']as$type)if(!in_array($type,$types,true))throw new RuntimeException('movement '.$type);echo"StockLotControlIntegration OK\n";}finally{$pdo->rollBack();}
